function [c] = gyro_counts(w, s)
%GYRO_COUNTS  The gyro's rate w (body) as its response's counts.
%   w: real[rad/s][3] (passed in 1/s)
%   s: EmuScale (passed rec)
%   returns c: int[3] (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    c = zeros(3, 1);
    c = zeros(3, 1);
    for i = (0):((3) - 1)
        c((i) + 1) = asils.models.emucodec.emu_count((w((i) + 1) / s.gyro), s.lo32, s.hi32);
    end
end
